+  function duckaiWebIntent(value){
+    const text=String(value||"").trim().replace(/^(?:hey|ok|please)\s+/i,"");
+    if(!/\bduck\.?ai\b/i.test(text))return null;
+    if(duckaiImagePrompt(text))return null;
+    if(/^(?:use|open|go(?:\s+to)?|launch|take me to|visit)\s+(?:the\s+)?duck\.?ai(?:\s+web)?\s*$/i.test(text)){
+      return {open:true,query:""};
+    }
+    const m=text.match(/^(?:use|using|search|search with|look up with|ask|try)\s+(?:the\s+)?duck\.?ai(?:\s+web)?(?:\s+(?:search|to\s+search))?\s*(?:for|about|on|:)?\s*(.+)$/i);
+    if(m&&m[1]&&m[1].trim())return {open:false,query:m[1].trim()};
+    if(/\b(?:web\s+search|search\s+the\s+web|look\s+up)\b/i.test(text)){
+      const q=text.replace(/^(?:use|using|please)\s+/i,"")
+        .replace(/\b(?:with|using|via|on)\s+(?:the\s+)?duck\.?ai(?:\s+web)?\b/gi,"")
+        .replace(/\b(?:web\s+search|search\s+the\s+web|look\s+up|for|about)\b/gi,"")
+        .replace(/\s+/g," ").trim();
+      if(q)return {open:false,query:q};
+    }
+    return null;
+  }
+  function duckaiImagePrompt(value){
+    const text=String(value||"").trim();
+    if(!text)return "";
+    const make=/\b(craet|creat(e|ing)?|mak(e|ing)|generat(e|ing)|draw|paint(ing)?|render(ing)?|image|imger|picture|pic|photo)\b/i;
+    const picture=/\b(imger|image|img|pictures?|pics?|photos?|artwork|illustration|wallpaper)\b/i;
+    if(!make.test(text)||!picture.test(text))return "";
+    if(/\b(video|clip|movie|film)\b/i.test(text)&&!/\b(image|imger|picture|pic|photo|artwork|illustration)\b/i.test(text))return "";
+    return text;
+  }
